<?php $pageTitle='Order Management';require '../includes/admin-header.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('UPDATE orders SET order_status=?,payment_status=? WHERE id=?')->execute([$_POST['order_status'],$_POST['payment_status'],(int)$_POST['id']]);flash('success','Order updated.');go('admin/orders.php');}$orders=$pdo->query('SELECT o.*,u.full_name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC')->fetchAll(); ?><div class="card table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Shipping</th><th>Status</th><th>Payment</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?=e($o['order_number'])?><br><small><?=date('d M Y',strtotime($o['created_at']))?></small></td><td><?=e($o['full_name'])?></td><td><?=money($o['total_amount'])?></td><td><small><?=e($o['shipping_address'])?></small></td><td colspan="2"><form method="post" class="d-flex gap-1"><input type="hidden" name="id" value="<?=$o['id']?>"><select class="form-select form-select-sm" name="order_status"><?php foreach(['pending','confirmed','packed','shipped','out_for_delivery','delivered','cancelled'] as $s): ?><option <?=$o['order_status']===$s?'selected':''?>><?=$s?></option><?php endforeach ?></select><select class="form-select form-select-sm" name="payment_status"><?php foreach(['pending','paid','failed'] as $s): ?><option <?=$o['payment_status']===$s?'selected':''?>><?=$s?></option><?php endforeach ?></select><button class="btn btn-sm btn-dark">Save</button></form></td></tr><?php endforeach ?></tbody></table></div><?php require '../includes/admin-footer.php'; ?>
